-- Create profiles table for user data
CREATE TABLE isexy.profiles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,
  first_name TEXT NOT NULL,
  birth_date DATE NOT NULL,
  gender TEXT NOT NULL,
  sexual_orientation TEXT,
  interested_in TEXT[] DEFAULT '{}',
  looking_for TEXT,
  bio TEXT,
  school TEXT,
  job_title TEXT,
  company TEXT,
  city TEXT,
  country TEXT NOT NULL DEFAULT 'Canada',
  distance_preference INTEGER DEFAULT 80,
  age_min INTEGER DEFAULT 18,
  age_max INTEGER DEFAULT 50,
  show_gender BOOLEAN DEFAULT true,
  show_orientation BOOLEAN DEFAULT false,
  is_premium BOOLEAN DEFAULT false,
  subscription_tier TEXT DEFAULT 'free',
  subscription_expires_at TIMESTAMPTZ,
  likes_remaining INTEGER DEFAULT 100,
  super_likes_remaining INTEGER DEFAULT 1,
  boosts_remaining INTEGER DEFAULT 0,
  last_boost_at TIMESTAMPTZ,
  is_verified BOOLEAN DEFAULT false,
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Create profile photos table
CREATE TABLE isexy.profile_photos (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id UUID NOT NULL REFERENCES isexy.profiles(id) ON DELETE CASCADE,
  photo_url TEXT NOT NULL,
  position INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Create swipes/interactions table
CREATE TABLE isexy.swipes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  swiper_id UUID NOT NULL REFERENCES isexy.profiles(id) ON DELETE CASCADE,
  swiped_id UUID NOT NULL REFERENCES isexy.profiles(id) ON DELETE CASCADE,
  action TEXT NOT NULL CHECK (action IN ('like', 'super_like', 'pass')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(swiper_id, swiped_id)
);

-- Create matches table
CREATE TABLE isexy.matches (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  profile1_id UUID NOT NULL REFERENCES isexy.profiles(id) ON DELETE CASCADE,
  profile2_id UUID NOT NULL REFERENCES isexy.profiles(id) ON DELETE CASCADE,
  matched_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  is_active BOOLEAN DEFAULT true,
  last_message_at TIMESTAMPTZ,
  UNIQUE(profile1_id, profile2_id)
);

-- Create messages table
CREATE TABLE isexy.messages (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  match_id UUID NOT NULL REFERENCES isexy.matches(id) ON DELETE CASCADE,
  sender_id UUID NOT NULL REFERENCES isexy.profiles(id) ON DELETE CASCADE,
  content TEXT NOT NULL,
  is_read BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Create subscriptions table for Stripe integration
CREATE TABLE isexy.subscriptions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id UUID NOT NULL REFERENCES isexy.profiles(id) ON DELETE CASCADE,
  stripe_customer_id TEXT,
  stripe_subscription_id TEXT,
  tier TEXT NOT NULL DEFAULT 'free',
  status TEXT NOT NULL DEFAULT 'inactive',
  current_period_start TIMESTAMPTZ,
  current_period_end TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Create reports table for safety
CREATE TABLE isexy.reports (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  reporter_id UUID NOT NULL REFERENCES isexy.profiles(id) ON DELETE CASCADE,
  reported_id UUID NOT NULL REFERENCES isexy.profiles(id) ON DELETE CASCADE,
  reason TEXT NOT NULL,
  description TEXT,
  status TEXT DEFAULT 'pending',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Create blocks table
CREATE TABLE isexy.blocks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  blocker_id UUID NOT NULL REFERENCES isexy.profiles(id) ON DELETE CASCADE,
  blocked_id UUID NOT NULL REFERENCES isexy.profiles(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(blocker_id, blocked_id)
);

