  FOR UPDATE USING (
    profile1_id IN (SELECT id FROM isexy.profiles WHERE user_id = auth.uid()) OR
    profile2_id IN (SELECT id FROM isexy.profiles WHERE user_id = auth.uid())
  );

-- Messages policies
CREATE POLICY "Users can view messages in their matches" ON isexy.messages
  FOR SELECT USING (
    match_id IN (
      SELECT id FROM isexy.matches 
      WHERE profile1_id IN (SELECT id FROM isexy.profiles WHERE user_id = auth.uid())
