-- Create function to update timestamps
CREATE OR REPLACE FUNCTION isexy.update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SET search_path = isexy, extensions;

-- Create triggers for updated_at
CREATE TRIGGER update_profiles_updated_at
  BEFORE UPDATE ON isexy.profiles
  FOR EACH ROW EXECUTE FUNCTION isexy.update_updated_at_column();

CREATE TRIGGER update_subscriptions_updated_at
  BEFORE UPDATE ON isexy.subscriptions
  FOR EACH ROW EXECUTE FUNCTION isexy.update_updated_at_column();

-- Create function to check for mutual likes and create matches
CREATE OR REPLACE FUNCTION isexy.check_and_create_match()
RETURNS TRIGGER AS $$
DECLARE
  mutual_swipe RECORD;
  new_match_id UUID;
BEGIN
  -- Only check for likes and super_likes
  IF NEW.action IN ('like', 'super_like') THEN
    -- Check if the other person already liked this user
    SELECT * INTO mutual_swipe FROM isexy.swipes 
    WHERE swiper_id = NEW.swiped_id 
      AND swiped_id = NEW.swiper_id 
      AND action IN ('like', 'super_like');
    
    IF FOUND THEN
      -- Create a match (ensure consistent ordering to avoid duplicates)
      INSERT INTO isexy.matches (profile1_id, profile2_id)
      VALUES (
        LEAST(NEW.swiper_id, NEW.swiped_id),
        GREATEST(NEW.swiper_id, NEW.swiped_id)
      )
      ON CONFLICT (profile1_id, profile2_id) DO NOTHING;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SET search_path = isexy, extensions SECURITY DEFINER;

-- Create trigger for match creation
CREATE TRIGGER on_swipe_check_match
  AFTER INSERT ON isexy.swipes
  FOR EACH ROW EXECUTE FUNCTION isexy.check_and_create_match();

