-- Create admin_users view to list users who can be assigned tickets
CREATE OR REPLACE VIEW isexy.admin_users AS
SELECT 
  ur.user_id,
  ur.role,
  p.first_name,
  p.id as profile_id
FROM isexy.user_roles ur
LEFT JOIN isexy.profiles p ON p.user_id = ur.user_id
WHERE ur.role IN ('admin', 'moderator');
;

