-- Forum posts policies
CREATE POLICY "Anyone can view forum posts" ON isexy.forum_posts
  FOR SELECT USING (true);

CREATE POLICY "Authenticated users can create posts" ON isexy.forum_posts
  FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);

CREATE POLICY "Users can update own posts" ON isexy.forum_posts
  FOR UPDATE USING (author_id IN (SELECT id FROM profiles WHERE user_id = auth.uid()));

CREATE POLICY "Users can delete own posts" ON isexy.forum_posts
  FOR DELETE USING (author_id IN (SELECT id FROM profiles WHERE user_id = auth.uid()) OR has_role(auth.uid(), 'admin'::app_role));

