DROP FUNCTION IF EXISTS isexy.increment_reply_count();

CREATE OR REPLACE FUNCTION isexy.increment_reply_count()
RETURNS TRIGGER AS $$
BEGIN
  UPDATE isexy.forum_posts SET reply_count = reply_count + 1 WHERE id = NEW.post_id;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = isexy, extensions;

CREATE TRIGGER on_reply_insert
  AFTER INSERT ON isexy.forum_replies
  FOR EACH ROW
  EXECUTE FUNCTION isexy.increment_reply_count();

