ON isexy.message_translations FOR SELECT
USING (
  EXISTS (
    SELECT 1 FROM isexy.messages m
    JOIN isexy.matches mt ON m.match_id = mt.id
    JOIN isexy.profiles p ON p.id = mt.profile1_id OR p.id = mt.profile2_id
    WHERE m.id = message_id AND p.user_id = auth.uid()
  )
);

CREATE POLICY "Users can insert translations for their messages"
ON isexy.message_translations FOR INSERT
WITH CHECK (
  EXISTS (
    SELECT 1 FROM isexy.messages m
    JOIN isexy.matches mt ON m.match_id = mt.id
    JOIN isexy.profiles p ON p.id = mt.profile1_id OR p.id = mt.profile2_id
    WHERE m.id = message_id AND p.user_id = auth.uid()
  )
);

