CREATE TRIGGER update_double_date_pairs_updated_at
BEFORE UPDATE ON isexy.double_date_pairs
FOR EACH ROW
EXECUTE FUNCTION isexy.update_updated_at_column();

CREATE TRIGGER update_double_date_settings_updated_at
BEFORE UPDATE ON isexy.double_date_settings
FOR EACH ROW
