-- 5. Match-creation trigger: validate swiper ownership
CREATE OR REPLACE FUNCTION isexy.check_and_create_match()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  mutual_swipe RECORD;
BEGIN
  -- Defense-in-depth: ensure caller owns the swiper profile (skipped for service role calls where auth.uid() is null)
  IF auth.uid() IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM isexy.profiles
    WHERE id = NEW.swiper_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Unauthorized swipe insert';
  END IF;

  IF NEW.action IN ('like', 'super_like') THEN
    SELECT * INTO mutual_swipe FROM isexy.swipes
    WHERE swiper_id = NEW.swiped_id
      AND swiped_id = NEW.swiper_id
      AND action IN ('like', 'super_like');
    IF FOUND THEN
      INSERT INTO isexy.matches (profile1_id, profile2_id)
      VALUES (
        LEAST(NEW.swiper_id, NEW.swiped_id),
        GREATEST(NEW.swiper_id, NEW.swiped_id)
      )
      ON CONFLICT (profile1_id, profile2_id) DO NOTHING;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
;

