-- ============================================================
-- from Lovable migration 20260511041942_ba5e2cd9-8f54-4260-9b3d-084f5db91e1f.sql
-- ============================================================
-- Drop broad receiver UPDATE policy
DROP POLICY IF EXISTS "Receiver can mark replies as read" ON isexy.phone_line_voice_replies;

-- Secure RPC: only receiver can mark their reply as read
CREATE OR REPLACE FUNCTION isexy.mark_voice_reply_read(p_reply_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  v_profile_id uuid;
  v_reply isexy.phone_line_voice_replies%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  SELECT id INTO v_profile_id FROM isexy.profiles WHERE user_id = auth.uid();
  IF v_profile_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'no_profile');
  END IF;

  SELECT * INTO v_reply FROM isexy.phone_line_voice_replies WHERE id = p_reply_id;
  IF v_reply.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;

  IF v_reply.to_profile_id <> v_profile_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;

  UPDATE isexy.phone_line_voice_replies
     SET is_read = true, updated_at = now()
   WHERE id = p_reply_id;

  RETURN jsonb_build_object('success', true);
END;
$$;
;

