-- 3. Retention ----------------------------------------------------------------
CREATE OR REPLACE FUNCTION isexy.purge_old_telemetry()
RETURNS VOID
LANGUAGE sql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
  DELETE FROM isexy.analytics_events WHERE created_at < now() - interval '395 days';
  DELETE FROM isexy.client_errors WHERE created_at < now() - interval '90 days';
$$;

