;

-- ============================================================
-- from Lovable migration 20261007140000_secure_rpcs_and_discover_feed.sql
-- ============================================================
-- Security hardening + fast Discover feed.
--
-- 1. Several SECURITY DEFINER functions accepted a profile id from the client
--    without checking it belongs to the caller, so any signed-in (or anonymous)
--    client could like as someone else, spend another member's likes, boosts,
--    credits or coupons. Each one is renamed to *_unchecked (not callable by
--    clients) and replaced by a same-named wrapper that verifies ownership
--    first. Business logic is untouched. Server-side callers (service role,
--    e.g. the Stripe webhook) keep working.
-- 2. get_discover_feed(): the whole Discover deck in one round trip instead of
--    3 queries + one photo query per profile.

-- Ownership guard --------------------------------------------------------------
CREATE OR REPLACE FUNCTION isexy.assert_profile_owner(p_profile_id UUID)
RETURNS VOID
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
BEGIN
  IF coalesce(auth.role(), '') = 'service_role' THEN
    RETURN;
  END IF;
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM isexy.profiles WHERE id = p_profile_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'not allowed for this profile' USING ERRCODE = '42501';
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION isexy.assert_profile_owner(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION isexy.assert_profile_owner(UUID) TO authenticated, service_role;

-- Rename the original once (idempotent), revoke client access to it.
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT * FROM (VALUES
      ('perform_like', 'uuid, uuid, text'),
      ('check_swipe_rate_limit', 'uuid'),
      ('use_boost', 'uuid, text'),
      ('redeem_coupon', 'text, uuid'),
      ('unlock_conversation', 'uuid, uuid, text'),
      ('sync_entitlements', 'uuid')
    ) AS t(fn, args)
  LOOP
    IF to_regprocedure(format('isexy.%I(%s)', r.fn, r.args)) IS NOT NULL
       AND to_regprocedure(format('isexy.%I(%s)', r.fn || '_unchecked', r.args)) IS NULL THEN
      EXECUTE format('ALTER FUNCTION isexy.%I(%s) RENAME TO %I', r.fn, r.args, r.fn || '_unchecked');
    END IF;
    IF to_regprocedure(format('isexy.%I(%s)', r.fn || '_unchecked', r.args)) IS NOT NULL THEN
      EXECUTE format('REVOKE ALL ON FUNCTION isexy.%I(%s) FROM PUBLIC, anon, authenticated', r.fn || '_unchecked', r.args);
      EXECUTE format('GRANT EXECUTE ON FUNCTION isexy.%I(%s) TO service_role', r.fn || '_unchecked', r.args);
    END IF;
  END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION isexy.perform_like(p_swiper_id UUID, p_swiped_id UUID, p_action TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = isexy, extensions AS $$
BEGIN
  PERFORM isexy.assert_profile_owner(p_swiper_id);
  RETURN isexy.perform_like_unchecked(p_swiper_id, p_swiped_id, p_action);
END;
$$;

