-- Discover feed ----------------------------------------------------------------
CREATE OR REPLACE FUNCTION isexy.normalize_gender(p_value TEXT)
RETURNS TEXT
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE
    WHEN v IN ('man', 'male', 'men', 'm') THEN 'men'
    WHEN v IN ('woman', 'female', 'women', 'w', 'f') THEN 'women'
    WHEN v IN ('nonbinary', 'non-binary', 'non binary', 'nb', 'enby') THEN 'nonbinary'
    WHEN v IN ('everyone', 'all', 'any') THEN 'everyone'
    ELSE v
  END
  FROM (SELECT lower(btrim(coalesce(p_value, ''))) AS v) s;
$$;

CREATE INDEX IF NOT EXISTS profile_photos_profile_position_idx ON isexy.profile_photos (profile_id, position);
CREATE INDEX IF NOT EXISTS swipes_swiper_idx ON isexy.swipes (swiper_id);

/**
 * The caller's Discover deck, ranked, with photos, in one call.
 * Mutual gender preferences, the caller's age range (always 18+), blocks in
 * both directions, already-swiped and shadow-banned profiles are excluded.
 * p_exclude lets the client page without re-receiving cards it already holds.
 * p_interests (optional) keeps profiles with at least one matching interest
 * (case-insensitive substring), used by Explore categories.
 */
CREATE OR REPLACE FUNCTION isexy.get_discover_feed(
  p_limit INTEGER DEFAULT 30,
  p_exclude UUID[] DEFAULT '{}',
  p_verified_only BOOLEAN DEFAULT false,
  p_interests TEXT[] DEFAULT NULL
)
RETURNS TABLE (
  id UUID,
  first_name TEXT,
  birth_date DATE,
  bio TEXT,
  city TEXT,
  job_title TEXT,
  company TEXT,
  school TEXT,
  is_verified BOOLEAN,
  interests TEXT[],
  distance_km INTEGER,
  photos TEXT[]
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
  WITH me AS (
    SELECT p.*
    FROM profiles p
    WHERE p.user_id = auth.uid()
    LIMIT 1
  ),
  window_ AS (
    SELECT
      (current_date - make_interval(years => greatest(18, coalesce(me.age_min, 18))))::date AS max_birth,
      ((current_date - make_interval(years => least(99, coalesce(me.age_max, 99)) + 1))::date + 1) AS min_birth
    FROM me
  ),
  candidates AS (
    SELECT
      c.*,
      (SELECT array_agg(ph.photo_url ORDER BY ph.position)
         FROM profile_photos ph WHERE ph.profile_id = c.id) AS photo_urls,
      CASE
        WHEN me.latitude IS NOT NULL AND c.latitude IS NOT NULL THEN
          round(6371 * 2 * asin(sqrt(
            power(sin(radians(c.latitude - me.latitude) / 2), 2) +
            cos(radians(me.latitude)) * cos(radians(c.latitude)) *
            power(sin(radians(coalesce(c.longitude, 0) - coalesce(me.longitude, 0)) / 2), 2)
          )))::int
      END AS dist
    FROM profiles c, me, window_
    WHERE c.id <> me.id
      AND c.is_active = true
      AND coalesce(c.shadow_banned, false) = false
      AND c.first_name IS NOT NULL
      AND c.birth_date BETWEEN window_.min_birth AND window_.max_birth
      AND (NOT p_verified_only OR c.is_verified = true)
      AND NOT (c.id = ANY (coalesce(p_exclude, '{}')))
      AND (
        p_interests IS NULL OR cardinality(p_interests) = 0 OR EXISTS (
          SELECT 1 FROM unnest(coalesce(c.interests, '{}')) i, unnest(p_interests) q
          WHERE lower(i) LIKE '%' || lower(q) || '%'
        )
      )
      AND NOT EXISTS (SELECT 1 FROM swipes s WHERE s.swiper_id = me.id AND s.swiped_id = c.id)
      AND NOT EXISTS (
        SELECT 1 FROM blocks b
        WHERE (b.blocker_id = me.id AND b.blocked_id = c.id)
           OR (b.blocker_id = c.id AND b.blocked_id = me.id)
      )
      -- They match what I'm looking for…
      AND EXISTS (
        SELECT 1 FROM unnest(coalesce(me.interested_in, '{}')) pref
        WHERE normalize_gender(pref) IN ('everyone', normalize_gender(c.gender))
      )
      -- …and I match what they're looking for.
      AND EXISTS (
        SELECT 1 FROM unnest(coalesce(c.interested_in, '{}')) pref
        WHERE normalize_gender(pref) IN ('everyone', normalize_gender(me.gender))
      )
  ),
  scored AS (
    SELECT
      c.*,
      (
        (coalesce(cardinality(c.photo_urls), 0) * 7
         + CASE WHEN length(coalesce(c.bio, '')) >= 10 THEN 20 ELSE 0 END
         + CASE WHEN coalesce(cardinality(c.interests), 0) >= 3 THEN 12 ELSE 0 END
         + CASE WHEN c.is_verified THEN 8 ELSE 0 END
         + CASE WHEN c.job_title IS NOT NULL AND c.job_title <> '' THEN 8 ELSE 0 END
         + CASE WHEN c.school IS NOT NULL AND c.school <> '' THEN 6 ELSE 0 END
         + CASE WHEN c.city IS NOT NULL AND c.city <> '' THEN 6 ELSE 0 END)
        * CASE c.subscription_tier WHEN 'platinum' THEN 2.0 WHEN 'gold' THEN 1.5 WHEN 'plus' THEN 1.2 ELSE 1.0 END
        * CASE
            WHEN c.super_boost_until > now() THEN 5
            WHEN c.last_boost_at > now() - interval '30 minutes' THEN 3
            ELSE 1
          END
      ) AS score
    FROM candidates c
    WHERE cardinality(c.photo_urls) > 0
  )
  SELECT
    s.id, s.first_name, s.birth_date, s.bio, s.city, s.job_title, s.company, s.school,
    coalesce(s.is_verified, false), s.interests, s.dist, s.photo_urls
  FROM scored s
  ORDER BY s.score DESC, s.dist ASC NULLS LAST, s.id
  LIMIT greatest(1, least(coalesce(p_limit, 30), 50));
$$;

REVOKE ALL ON FUNCTION isexy.get_discover_feed(INTEGER, UUID[], BOOLEAN, TEXT[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.get_discover_feed(INTEGER, UUID[], BOOLEAN, TEXT[]) TO authenticated;
;

-- ============================================================
-- from Lovable migration 20261007150000_conversations_inbox.sql
-- ============================================================
-- Inbox in one query.
-- The Matches screen used to run 5 queries per match (profile, photo, unread,
-- unlock, last message): 200 requests for 40 matches. get_my_conversations()
-- returns the whole inbox for the signed-in member in a single call.

CREATE INDEX IF NOT EXISTS messages_match_created_idx ON isexy.messages (match_id, created_at DESC);
CREATE INDEX IF NOT EXISTS messages_unread_idx ON isexy.messages (match_id, sender_id) WHERE is_read = false;
CREATE INDEX IF NOT EXISTS matches_profile1_idx ON isexy.matches (profile1_id) WHERE is_active = true;
CREATE INDEX IF NOT EXISTS matches_profile2_idx ON isexy.matches (profile2_id) WHERE is_active = true;

CREATE OR REPLACE FUNCTION isexy.get_my_conversations()
RETURNS TABLE (
  match_id UUID,
  matched_at TIMESTAMPTZ,
  other_id UUID,
  first_name TEXT,
  photo_url TEXT,
  is_verified BOOLEAN,
  last_active_at TIMESTAMPTZ,
  last_message_at TIMESTAMPTZ,
  last_message_preview TEXT,
  last_message_mine BOOLEAN,
  unread_count INTEGER,
  is_unlocked BOOLEAN
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
  WITH me AS (
    SELECT id, coalesce(is_premium, false) AS premium FROM profiles WHERE user_id = auth.uid() LIMIT 1
  ),
  my_matches AS (
    SELECT m.id, m.matched_at, m.last_message_at,
           CASE WHEN m.profile1_id = me.id THEN m.profile2_id ELSE m.profile1_id END AS other_id
    FROM matches m, me
    WHERE m.is_active = true AND (m.profile1_id = me.id OR m.profile2_id = me.id)
  )
  SELECT
    mm.id,
    mm.matched_at,
    mm.other_id,
    o.first_name,
    (SELECT ph.photo_url FROM profile_photos ph WHERE ph.profile_id = mm.other_id ORDER BY ph.position LIMIT 1),
    coalesce(o.is_verified, false),
    o.last_active_at,
    coalesce(lm.created_at, mm.last_message_at),
    left(lm.content, 140),
    lm.sender_id = me.id,
    (SELECT count(*)::int FROM messages u WHERE u.match_id = mm.id AND u.sender_id <> me.id AND u.is_read = false),
    me.premium OR EXISTS (
      SELECT 1 FROM conversation_unlocks cu
      WHERE cu.match_id = mm.id AND cu.unlocked_by = me.id AND cu.unlock_type = 'chat'
    )
  FROM my_matches mm
  CROSS JOIN me
  JOIN profiles o ON o.id = mm.other_id
  LEFT JOIN LATERAL (
    SELECT msg.content, msg.created_at, msg.sender_id
    FROM messages msg WHERE msg.match_id = mm.id
    ORDER BY msg.created_at DESC LIMIT 1
  ) lm ON true
  WHERE NOT EXISTS (
    SELECT 1 FROM blocks b
    WHERE (b.blocker_id = me.id AND b.blocked_id = mm.other_id)
       OR (b.blocker_id = mm.other_id AND b.blocked_id = me.id)
  )
  ORDER BY coalesce(lm.created_at, mm.last_message_at, mm.matched_at) DESC;
$$;

REVOKE ALL ON FUNCTION isexy.get_my_conversations() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION isexy.get_my_conversations() TO authenticated;
;

-- ============================================================
-- from Lovable migration 20261007160000_otp_bruteforce_protection.sql
-- ============================================================
-- OTP hardening.
--
-- verify_otp() had no attempt limit and is callable by anyone, so a 6-digit
-- password-reset code could be brute-forced (a failed guess cost nothing):
-- request a reset for a victim's email, then guess until it matches and
-- change their password. Now each code allows 5 wrong guesses, then it is
-- burned and a new one must be requested (send-email-otp allows 3 per hour).
-- Emails are compared case-insensitively.

ALTER TABLE isexy.otp_codes ADD COLUMN IF NOT EXISTS attempts INTEGER NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS otp_codes_lookup_idx ON isexy.otp_codes (lower(email), type, created_at DESC) WHERE used_at IS NULL;

CREATE OR REPLACE FUNCTION isexy.verify_otp(p_email TEXT, p_code TEXT, p_type TEXT)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = isexy, extensions
AS $$
DECLARE
  v_otp isexy.otp_codes%ROWTYPE;
  v_max_attempts CONSTANT INTEGER := 5;
BEGIN
  -- The newest live code for this email/type, locked so parallel guesses
  -- are counted one by one.
  SELECT * INTO v_otp
  FROM isexy.otp_codes
  WHERE lower(email) = lower(btrim(p_email))
    AND type = p_type
    AND used_at IS NULL
    AND expires_at > now()
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN json_build_object('valid', false, 'error', 'Invalid or expired code');
  END IF;

  IF v_otp.attempts >= v_max_attempts THEN
    UPDATE isexy.otp_codes SET used_at = now() WHERE id = v_otp.id;
    RETURN json_build_object('valid', false, 'error', 'Too many attempts. Request a new code.');
  END IF;

  IF v_otp.code IS DISTINCT FROM btrim(coalesce(p_code, '')) THEN
    UPDATE isexy.otp_codes
    SET attempts = attempts + 1,
        used_at = CASE WHEN attempts + 1 >= v_max_attempts THEN now() ELSE used_at END
    WHERE id = v_otp.id;
    RETURN json_build_object(
      'valid', false,
      'error', CASE WHEN v_otp.attempts + 1 >= v_max_attempts
                    THEN 'Too many attempts. Request a new code.'
                    ELSE 'Invalid code' END,
      'attempts_left', greatest(0, v_max_attempts - v_otp.attempts - 1)
    );
  END IF;

  UPDATE isexy.otp_codes SET used_at = now() WHERE id = v_otp.id;
  RETURN json_build_object('valid', true, 'email', lower(btrim(p_email)));
END;
$$;

REVOKE ALL ON FUNCTION isexy.verify_otp(TEXT, TEXT, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION isexy.verify_otp(TEXT, TEXT, TEXT) TO anon, authenticated, service_role;

-- Exact account lookup for server-side flows (update-user-password used
-- auth.admin.listUsers(), which only returns the first page of 50 users).
CREATE OR REPLACE FUNCTION isexy.get_auth_user_id_by_email(p_email TEXT)
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = isexy, extensions, auth
AS $$
  SELECT id FROM auth.users WHERE lower(email) = lower(btrim(p_email)) LIMIT 1;
$$;

REVOKE ALL ON FUNCTION isexy.get_auth_user_id_by_email(TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION isexy.get_auth_user_id_by_email(TEXT) TO service_role;
;

-- ============================================================
-- from Lovable migration 20261007170000_calls_realtime.sql
-- ============================================================
-- Make in-app calling work end to end.
--
-- IncomingCallNotification listens for INSERTs on video_call_sessions over
-- Realtime, but the table was never added to the supabase_realtime
-- publication, so receivers never saw an incoming call. The caller also needs
-- UPDATE events to learn that a call was declined.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'isexy' AND tablename = 'video_call_sessions'
  ) THEN
    PERFORM isexy._realtime_add('video_call_sessions');
  END IF;
END;
$$;

-- Phone vs video, so the receiver answers with the right media.
ALTER TABLE isexy.video_call_sessions
  ADD COLUMN IF NOT EXISTS call_type TEXT NOT NULL DEFAULT 'video';

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'video_call_sessions_call_type_check') THEN
    ALTER TABLE isexy.video_call_sessions
      ADD CONSTRAINT video_call_sessions_call_type_check CHECK (call_type IN ('video', 'phone'));
  END IF;
END;
$$;

CREATE INDEX IF NOT EXISTS video_call_sessions_receiver_status_idx
  ON isexy.video_call_sessions (receiver_id, status, created_at DESC);

-- Only ring someone you're actually matched with (the insert policy only
-- checked that the caller was yourself, so any member could ring anyone).
DROP POLICY IF EXISTS "Users can insert call sessions" ON isexy.video_call_sessions;
CREATE POLICY "Users can insert call sessions"
ON isexy.video_call_sessions FOR INSERT
WITH CHECK (
  EXISTS (SELECT 1 FROM isexy.profiles p WHERE p.id = video_call_sessions.caller_id AND p.user_id = auth.uid())
  AND EXISTS (
    SELECT 1 FROM isexy.matches m
    WHERE m.id = video_call_sessions.match_id
      AND m.is_active = true
      AND (
        (m.profile1_id = video_call_sessions.caller_id AND m.profile2_id = video_call_sessions.receiver_id)
        OR (m.profile2_id = video_call_sessions.caller_id AND m.profile1_id = video_call_sessions.receiver_id)
      )
  )
);
;
